import unicodedata
import hashlib
import hmac
import os
import re
from flask import Flask, request, jsonify, g
from functools import wraps
import sqlite3

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)

DB_PATH = '/tmp/multitenant.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS tenants (
        id INTEGER PRIMARY KEY,
        name TEXT UNIQUE NOT NULL,
        api_key TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        tenant_name TEXT NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        classification TEXT DEFAULT 'internal'
    )''')
    db.commit()
    db.close()

def normalize_tenant_id(raw_tenant):
    """Normalize tenant identifier for consistent storage and lookup.
    Uses NFKC normalization to handle equivalent Unicode representations."""
    stripped = raw_tenant.strip()
    normalized = unicodedata.normalize('NFKC', stripped)
    return normalized

def sanitize_for_storage(text):
    """Sanitize text before storage - remove control characters."""
    cleaned = ''.join(ch for ch in text if unicodedata.category(ch)[0] != 'C')
    return cleaned

def validate_tenant_name(name):
    """Validate tenant name format after normalization."""
    if not name or len(name) > 64:
        return False
    if not re.match(r'^[a-zA-Z0-9_\-\.]+$', name):
        return False
    return True

def resolve_tenant_context(api_key, claimed_tenant):
    """Resolve and verify tenant context from API key and claimed tenant.
    Returns the authorized tenant name or None."""
    db = get_db()
    row = db.execute(
        'SELECT name FROM tenants WHERE api_key = ?', (api_key,)
    ).fetchone()
    if row is None:
        return None
    authorized_tenant = row['name']
    # Normalize the claimed tenant for comparison
    normalized_claim = normalize_tenant_id(claimed_tenant)
    # Compare normalized forms
    if normalized_claim == authorized_tenant:
        return authorized_tenant
    return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        claimed_tenant = request.headers.get('X-Tenant-ID')
        if not api_key or not claimed_tenant:
            return jsonify({'error': 'Missing authentication'}), 401
        tenant = resolve_tenant_context(api_key, claimed_tenant)
        if tenant is None:
            return jsonify({'error': 'Unauthorized'}), 403
        g.tenant = tenant
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    """List documents for the authenticated tenant."""
    db = get_db()
    # Use the verified tenant from auth context
    rows = db.execute(
        'SELECT id, title, classification FROM documents WHERE tenant_name = ?',
        (g.tenant,)
    ).fetchall()
    return jsonify([dict(r) for r in rows])

@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    """Create a document under the authenticated tenant."""
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    title = sanitize_for_storage(data['title'])
    content = sanitize_for_storage(data['content'])
    classification = data.get('classification', 'internal')
    db = get_db()
    db.execute(
        'INSERT INTO documents (tenant_name, title, content, classification) VALUES (?, ?, ?, ?)',
        (g.tenant, title, content, classification)
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    """Retrieve a specific document with tenant isolation."""
    db = get_db()
    row = db.execute(
        'SELECT * FROM documents WHERE id = ? AND tenant_name = ?',
        (doc_id, g.tenant)
    ).fetchone()
    if row is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(row))

@app.route('/admin/tenants', methods=['POST'])
def register_tenant():
    """Register a new tenant (admin endpoint)."""
    admin_token = request.headers.get('X-Admin-Token')
    configured_token = os.environ.get('ADMIN_TOKEN', '')
    # Reject if admin token is not configured, or if provided token is missing.
    if not configured_token or not admin_token:
        return jsonify({'error': 'Forbidden'}), 403
    # Constant-time comparison to avoid timing attacks.
    if not hmac.compare_digest(admin_token, configured_token):
        return jsonify({'error': 'Forbidden'}), 403
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Missing name'}), 400
    tenant_name = data['name']
    if not validate_tenant_name(tenant_name):
        return jsonify({'error': 'Invalid tenant name'}), 400
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()
    db = get_db()
    try:
        db.execute(
            'INSERT INTO tenants (name, api_key) VALUES (?, ?)',
            (tenant_name, api_key)
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Tenant exists'}), 409
    return jsonify({'name': tenant_name, 'api_key': api_key}), 201

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
